package com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.document;
import java.util.List; import org.springframework.stereotype.Service; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.web.multipart.MultipartFile; import com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.entity.*; import com.StudentManagementwithloginlogout.StudentManagementwithloginlogout.repository.*; import jakarta.servlet.http.HttpSession;
@Service public class DocumentService { @Autowired ContractDocumentRepository repo; @Autowired ContractRepository contracts; @Autowired HttpSession session;
 public ContractDocument upload(Long id,MultipartFile file) throws Exception {if(file==null||file.isEmpty()) throw new IllegalArgumentException("File is required"); Contract c=contracts.findById(id).orElseThrow(()->new IllegalArgumentException("Contract not found")); Object u=session.getAttribute("loggedUser"); String by=u instanceof User?((User)u).getEmail():"SYSTEM"; return repo.save(new ContractDocument(c,file.getOriginalFilename(),file.getContentType(),file.getSize(),file.getBytes(),by));}
 public List<ContractDocument> list(Long id){return repo.findByContractIdOrderByUploadedAtDesc(id);} public ContractDocument get(Long id){return repo.findById(id).orElseThrow(()->new IllegalArgumentException("Document not found"));}
}
